"use client";

import dynamic from "next/dynamic";

/**
 * The footer's jigsaw wordmark, drawn in the browser only. Its ~360 pieces are generated by code, so shipping the
 * code is tiny, but rendering them on the server put ~2 MB of SVG paths into the HTML of every page (and ~2 GB into
 * the server image, across the prerendered pages). Until it draws, an empty box of the same shape holds its place,
 * so the founders positioned over it don't move.
 */
const PuzzleWordmark = dynamic(() => import("./PuzzleWordmark").then((m) => m.PuzzleWordmark), {
  ssr: false,
  loading: () => <div aria-hidden className="w-full" style={{ aspectRatio: "900 / 256" }} />,
});

export function PuzzleWordmarkDeferred({ className }: { className?: string }) {
  return <PuzzleWordmark className={className} />;
}
